package com.yeyamo_mobile.api.partner_service.domain.model;
import static org.assertj.core.api.Assertions.*;import org.junit.jupiter.api.Test;
class PartnerTests{@Test void startsAsDraft(){Partner p=Partner.create("42","Yeyamo SARL",BusinessType.COMPANY,"contact@yeyamo.test");assertThat(p.getId()).isNotNull();assertThat(p.getStatus()).isEqualTo(PartnerStatus.DRAFT);assertThat(p.canEditDocuments()).isTrue();}@Test void submissionRequiresRegistrationAndDocument(){Partner p=Partner.create("42","Yeyamo",BusinessType.COMPANY,"c@y.test");assertThatThrownBy(()->p.submit(1)).isInstanceOf(IllegalStateException.class);p.update("Yeyamo",null,BusinessType.COMPANY,"RC-123",null,"c@y.test",null,null,null);assertThatThrownBy(()->p.submit(0)).isInstanceOf(IllegalStateException.class);p.submit(1);assertThat(p.getStatus()).isEqualTo(PartnerStatus.SUBMITTED);}@Test void approvalOnlyAfterSubmission(){Partner p=Partner.create("42","Yeyamo",BusinessType.COMPANY,"c@y.test");assertThatThrownBy(()->p.review(PartnerStatus.APPROVED,null,10)).isInstanceOf(IllegalStateException.class);p.update("Yeyamo",null,BusinessType.COMPANY,"RC-123",null,"c@y.test",null,null,null);p.submit(1);p.review(PartnerStatus.UNDER_REVIEW,null,10);p.review(PartnerStatus.APPROVED,"OK",5);assertThat(p.isPublic()).isTrue();assertThat(p.getVerifiedAt()).isNotNull();}}
